(window.PF_CAT_SHARD=window.PF_CAT_SHARD||{})["76452"]={"AU0381":{"i":"AU0381","entryRequirements":"Bachelor of Architecture or equivalent","strategicPurposeStatement":"Primarily aimed at those students who have completed the BArch and are interested in advanced research.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0381"},"CA2358":{"i":"CA2358","entryRequirements":"To be eligible for admission, applicants must either have a recognised undergraduate degree in the discipline of architecture with a grade point average of 4.0 or higher for all level 7 courses, or meet the special admission requirements. Applicants must","strategicPurposeStatement":"Graduates will: be capable of informed discussion and debate on contemporary architecture and related issues; contribute to the social and environmental context within which architecture takes place; engage the complexity of architectures techniques, procedures and protocols of implementation as material for creative exploration; formulate practices committed to public legibility, to the engagement of new technologies, and to creative means of implementation; be committed to new strategies of realisation and high levels of design practice; deliver innovation, plausibility, and high levels of technical resolution; embrace the technical and operative expertise necessary to innovate in a rapidly changing world; be able to critically appraise contemporary architectural production; have a thorough knowledge of architectural and urban design issues in Aotearoa New Zealand;  be capable of integrating knowledge from other fields into architectural design and practice.","developedBy":"Manukau Institute of Technology and Unitec - Unitec","qualityAssuredBy":"Quality Assurance Division, NZQA","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CA2358"},"AU5550":{"i":"AU5550","entryRequirements":"Must meet the entry requirements for the Master of Urban Planning (Professional).","strategicPurposeStatement":"Graduates will have developed high level skills, knowledge and understanding in a critical mix of practical and theoretical areas in more than one discipline within the built environment. They will understand the practical application of the theory to practice.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5550"},"AU5717":{"i":"AU5717","entryRequirements":"A relevant bachelors degree (excluding the Bachelor of Property) with a minimum GPA or a relevant bachelors degree and passed 60 points in the Postgraduate Certificate in Property Practice with a minimum GPA (180-point pathway); or a Postgraduate Diploma in Business in Property Management with a minimum GPA (120-point pathway).","strategicPurposeStatement":"Graduates of the MPropPrac will demonstrate advanced capabilities in a critical mix of practical and theoretical areas of study related to their area of specialisation in property practice, and be able to apply their analytical and solution-seeking skills to organisational challenges. They will be equipped to enter or progress in property careers.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5717"},"VI0041":{"i":"VI0041","entryRequirements":"A Bachelor of Building Science or Bachelor of Building Science (Hons)  or equivalent.","strategicPurposeStatement":"A graduate of the Master of Building Science programme will have acquired an advanced understanding of an area of study within the building science discipline.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0041"},"VI003J":{"i":"VI003J","entryRequirements":"A Postgraduate Diploma in Architectural Science from Victoria University of Wellington, or equivalent, with an average grade of at least B.","strategicPurposeStatement":"Graduates will have advanced-level understanding of architectural science in a range of contexts and scales, with an emphasis on research into a selected aspect of the built environment. They will be able to access, interpret, critique and apply relevant research and disciplinary tools within an academic context. Graduates will use their advanced knowledge to undertake and communicate research on aspects of the built environment and the building industry. Graduates will be well qualified to take on roles in academic units and research organisations related to the built environment and may be able to continue to doctoral study.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI003J"},"VI00V8":{"i":"VI00V8","entryRequirements":"A Bachelor of Architecture Studies degree in architecture or approved equivalent or Graduate Diploma in Designed Environments in architecture.","strategicPurposeStatement":"Graduates from the Master of Architecture (Professional) programme will have met the academic requirements for professional registration and will have demonstrated the ability to: independently research and analyse data, formulate design strategies and initiate new insights and approaches to architectural projects; implement a chosen design strategy consistently through all stages of the design process and understand the role of the professional architect in contemporary society.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00V8"},"MY0443":{"i":"MY0443","entryRequirements":"A four year honours degree, or a three year degree and postgraduate diploma in Construction or equivalent.","strategicPurposeStatement":"A graduate of the Master of Construction will be able to plan and undertake research and evaluate construction, cost management, project management or facilities management related processes, policies, practices, proposals and strategies, and make informed decisions.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0443"},"AU5523":{"i":"AU5523","entryRequirements":"Completed the requirements for a Bachelors in a relevant discipline excluding the Degrees of Bachelor of Planning, Bachelor of Urban Planning, Bachelor of Urban Planning (Honours).","strategicPurposeStatement":"Graduates will have developed high level skills, knowledge and understanding in a critical mix of practical and theoretical areas of study related to urban planning practice. They will be well-trained practitioners in their specific major and will be well equipped to pursue their professional careers.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5523"},"LI7403":{"i":"LI7403","entryRequirements":"To be considered for entry students must have:  * Achieved a minimum of 2nd class division 1 honours (or minimum average of 70% in their 300 level or higher courses and in their final year overall) in their previous university degree, and  * Achieved an IELTS score of 6.5 (no individual component less than 6.0)  * Submitted a portfolio. No prior qualification in art or design is required, but students should be able to demonstrated design-related skills and creativity. The folio may contain landscape architecture drawings, representational drawings, paintings, photography or technical drawings. It can also include drawings that demonstrate computer graphic skills.  * Demonstrated basic computer graphic skills in Vectorworks or AutoCAD. This can be demonstrated either in the portfolio or with a certificate of completion of an online course.  * Submitted a 1000-word argumentative essay on a reading that will be provided.  * Participated in an online or in-person interview.","strategicPurposeStatement":"The 240 credit Master of Landscape Architecture is intended to lead graduates to enter employment as professional Landscape Architects or advance to PhD study. A key outcome of the programme is that graduates will demonstrate advanced capabilities in the subject areas required for NZILA and IFLA accreditation. They will be well-rounded, creative and scholarly designers, in addition to researchers, in advancement of the profession of Landscape Architecture.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI7403"},"OO0540":{"i":"OO0540","entryRequirements":"A bachelor's degree with an average grade of B+, or equivalent.","strategicPurposeStatement":"Graduates will have a deep, coherent and extensive knowledge of development and planning in an international context and knowledge of the fundamental contribution of research to these disciplines.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0540"},"VI003L":{"i":"VI003L","entryRequirements":"A bachelor's degree in architectural studies or building science, or equivalent, with an average grade of at least B.","strategicPurposeStatement":"Graduates will use their knowledge of architectural science to improve the quality of the built environment, and will be able to write and present their ideas in a professional manner.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI003L"},"LI1002":{"i":"LI1002","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of the BLA (Graduate) will have professional skills in design practice and implementation.  Graduates will be able to create sustainable, high-quality environments with the most effective use of resources to create places and landscapes that enrich our identity, provide stimulating and uplifting experiences, meet socio-economic and functional needs, and sustain and enhance ecological and cultural values.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI1002"},"AU5551":{"i":"AU5551","entryRequirements":"Must meet the entry requirements for the Master of Urban Planning (Professional) and the Master of Heritage Conservation.","strategicPurposeStatement":"Graduates will have developed high level skills, knowledge and understanding in a critical mix of practical and theoretical areas in more than one discipline within the built environment. They will understand the practical application of the theory to practice.","graduateProfile":"Not applicable","educationPathway":"Not applicable","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5551"},"AU5729":{"i":"AU5729","entryRequirements":"Completed the requirements for a relevant Bachelors degree with a minimum GPA or completed the requirements for a relevant Bachelors Honours degree or postgraduate diploma with a minimum GPA.","strategicPurposeStatement":"MHousSt graduates will have developed advanced skills, knowledge and understanding of the theory and practice of housing design, sustainability, policy, economics, affordability, regulation and procurement, with a focus on the New Zealand situation. They will be experienced in the application of the theory into practice, through analysis of the industry and local case studies. They will be critical, reflective practitioners, able to pursue personal professional goals and higher level postgraduate research.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5729"},"AU5549":{"i":"AU5549","entryRequirements":"Must meet the entry requirements for the Master of Architecture (Professional) and the Master of Heritage Conservation.","strategicPurposeStatement":"Graduates will have developed high level skills, knowledge and understanding in a critical mix of practical and theoretical areas in more than one discipline within the built environment. They will understand the practical application of the theory to practice.","graduateProfile":"Not applicable","educationPathway":"Not applicable","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5549"},"AK1350":{"i":"AK1350","entryRequirements":"a relevant bachelor's degree with honours or  a relevant bachelor's degree and one year of advanced study or  a relevant bachelor's degree and relevant experience deemed equivalent to one year of advanced study","strategicPurposeStatement":"MADM graduates will be prepared for careers as Design Managers or similar roles where design management processes are required for complex construction projects. Graduates may also pursue more advanced studies at postgraduate level.","graduateProfile":"A range of summative assessments throughout the programme.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1350"},"VI004U":{"i":"VI004U","entryRequirements":"Completed a Bachelor Architectural Studies (BAS) degree or an equivalent qualification, with an average grade of at least a B","strategicPurposeStatement":"Graduates from the PGCertDE will have the knowledge and skills required to implement a chosen design strategy. They will have an understanding of the  role, legal and institutional contexts, and  frameworks pertaining to the area i.e. those of Architecture, Interior Architecture or Landscape Architecture. Landscape Architecture graduates will also be able to translate designs into documentation and engage with the institutional contexts which govern the practice of landscape architecture.   Graduates from the PGCertDE may be able to continue to the PGDipDE and to the MArch(Prof), MIA or MLA.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004U"},"AU5146":{"i":"AU5146","entryRequirements":"A bachelors degree in architecture or planning, or Master of Planning Practice or an approved equivalent qualification. Portfolio of work required.","strategicPurposeStatement":"MUrbDes graduates will be able to critically analyse the context for urban design, apply urban design theory and methods, and apply generic skills in graphic communication, visual literacy and design awareness, creativity and innovation, policy development, team work and codification.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5146"},"AU5547":{"i":"AU5547","entryRequirements":"Bachelor of Architectural Studies or an equivalent qualification;","strategicPurposeStatement":"Graduates will have high skill levels, knowledge and understanding in a mix of practical and theoretical areas in two disciplines within the built environment. They will understand the practical application of the theory to practice.","graduateProfile":"Not applicable","educationPathway":"Not applicable","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5547"},"VI005Y":{"i":"VI005Y","entryRequirements":"An approved Bachelor's degree in a relevant discipline with an average grade of at least B.","strategicPurposeStatement":"Graduates from the PGDipConsLaw will have a good level of understanding of construction law and a basic understanding of construction management. They can access, interpret and apply the relevant law pertinent to the construction issue at hand. Their advanced and specialised knowledge will allow them to improve the quality of their legal advice. Some graduates may choose to continue to the Master of Construction Law, the Master of Laws or Master of Architectural Science (Project Management).","graduateProfile":"The assessments for the courses will include individual and group assignments, tutorials, written reports, verbal presentations, reflective summaries, blogs and quizzes where appropriate.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005Y"},"AK1290":{"i":"AK1290","entryRequirements":"A bachelor's degree or equivalent and relevant engineering or managerial work experience.","strategicPurposeStatement":"Graduates will have covered advanced topics in management, business, project management and related engineering fields. They will have developed the knowledge and skills necessary for emerging and middle level construction managers.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1290"},"AU5536":{"i":"AU5536","entryRequirements":"A New Zealand university entrance qualification or overseas equivalent and submission of a supplementary written statement Admission to this programme is at the discretion of Senate or its representative.","strategicPurposeStatement":"Bachelor of Urban Planning (Honours) graduates will have developed high level skills, knowledge and understanding in a critical mix of practical and theoretical areas of study related to urban planning practice. They will be well-trained practitioners in their specific major and will be well equipped to pursue their professional careers.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5536"},"AK1349":{"i":"AK1349","entryRequirements":"Applicant must have completed the Bachelor of Architecture and Future Environments or equivalent, and must normally have completed the admission qualification with a B grade average or higher in courses at level 7.","strategicPurposeStatement":"Graduates of the PgDipArch will be able to integrate different strands of social and technical knowledge into core design processes  and to design a range of buildings at different scales and levels of complexity. They will be at ease working collaboratively, in multi-disciplinary teams or in diverse cultural settings.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1349"},"VI004T":{"i":"VI004T","entryRequirements":"Completed a Bachelor Architectural Studies (BAS) degree or an equivalent qualification, with an average grade of at least a B.","strategicPurposeStatement":"Graduates from the PGDipDE will be able to implement a chosen design strategy through all stages of the design process. They will have knowledge and skills relating to the role, legal and institutional contexts, and frameworks pertaining to the area i.e. those of Architecture, Interior Architecture or Landscape Architecture. Landscape Architecture graduates will also be able to translate designs into documentation and engage professionally with the institutional contexts which govern the practice of landscape architecture. Graduates from the PGDipDE may be able to continue to the MArch(Prof), MIA or MLA.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004T"},"AU5731":{"i":"AU5731","entryRequirements":"Must meet the admission requirements for the Degrees of Master of Urban Planning (Professional) and Master of Housing Studies.","strategicPurposeStatement":"MUrbPlan(Prof)HousSt graduates will have developed advanced skills, knowledge and understanding in a critical mix of practical and theoretical areas in urban planning and housing. They will be experienced in the application of the theory into practice, through analysis of the industry and local case studies relevant to careers as successful built-form professionals. They will be critical, reflective practitioners, able to pursue personal professional goals and higher level postgraduate research.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5731"},"VI005K":{"i":"VI005K","entryRequirements":"An approved Bachelor's degree in a relevant discipline with an average grade of at least B.","strategicPurposeStatement":"Graduates from the MURPlan programme will be able to demonstrate critical and effective use of planning knowledge and specific skills in professional planning careers in both the private and public sectors. Graduates will be able to access, critique and apply relevant planning solutions within interdisciplinary teams and allied professions based on a broad range of knowledge and skills derived from cultural, economic, environmental, governance, social and spatial approaches. Graduates will be prepared to take leading roles with intellectual autonomy, leadership and integrity in Aotearoa-New Zealand, Australasia and internationally.","graduateProfile":"The assessments for the courses will include individual and group assignments, tutorials, written reports, verbal presentations, reflective summaries, blogs, and quizzes where appropriate. Design outputs such as drawings, plans, posters, photographs, and videos will also be part of some courses with strong planning and design content.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005K"},"VI006G":{"i":"VI006G","entryRequirements":"1. (a) Before enrolment, a candidate for the MConst degree shall have:  (i) completed a BBSc, BConst or BAS degree or equivalent, with an average grade of at least B; and  (ii) been accepted by the head of school as capable of proceeding with the proposed course of study.  (b) Requirement (a)(i) may be waived by the Associate Dean (Students) of the Faculty of Architecture and Design Innovation for a candidate who has practical, professional, or scholarly experience that provides equivalent preparation.","strategicPurposeStatement":"Graduates will demonstrate the advanced knowledge, skills, and attributes necessary to excel in the dynamic and demanding construction industry, enabling them to contribute effectively to the planning, design, and execution of construction projects with rigorous academic and professional demands. They will possess a comprehensive understanding of construction management principles, sustainable practices, and cutting-edge technologies, enabling them to recognise the impact and importance of Maori knowledge and Te Tiriti of Waitangi in construction projects, critically analyse complex challenges and contribute to innovative solutions within the built environment sector. Graduates will demonstrate autonomy, critical thinking, problem-solving, professional integrity, and communication skills, as well as be able to navigate the complexities of the construction industry, including regulatory frameworks and cultural considerations.","graduateProfile":"A combination of individual and group assignments, including online exercises and activities, essays, laboratory and field assessments, in-class tests, examinations, oral presentations, and simulation exercises, together with work-integrated learning opportunities through a practicum or industry project that is assessed through a written report and oral presentation to supervisor and peers. Alternatively, a research thesis that demonstrates the student's mastery of the topic.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI006G"},"WI0259":{"i":"WI0259","entryRequirements":"Bachelor of Social Sciences with Honours, Master of Science or Postgraduate Diploma in Science, in Resources and Environmental Planning with at least a B grade average.","strategicPurposeStatement":"Graduates have specialist knowledge, breadth and depth of understanding, and independent judgement, in relation to planning practice. The MEP will provide graduates with a qualification that is recognised by the New Zealand Planning Institute as a qualification for membership.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0259"},"AU5730":{"i":"AU5730","entryRequirements":"Must meet the admission requirements for the Degrees of Master of Architecture (Professional) and Master of Housing Studies.","strategicPurposeStatement":"MArch(Prof)HousSt graduates will have developed advanced skills, knowledge and understanding in a critical mix of practical and theoretical areas in architecture and housing. They will be experienced in the application of the theory to practice, through design work and industry and local case studies relevant to careers as successful built-form professionals. They will be critical, reflective practitioners, able to pursue personal professional goals and higher level postgraduate research.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5730"},"VI00U7":{"i":"VI00U7","entryRequirements":"A Victoria University Bachelor of Architectural Studies degree in Landscape Architecture or a Graduate Diploma in Designed Environments in Landscape Architecture or, equivalent qualification.","strategicPurposeStatement":"Graduates from the Master of Landscape Architecture programme will have met the academic requirements for professional registration and will have demonstrated the ability to; translate developed designs into documentation; independently research and analyse data, formulate design strategies and initiate new insights and approaches to landscape projects; implement a chosen design strategy consistently through all stages of the design process; and engage professionally with the institutional contexts which govern the practice of landscape architecture.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00U7"},"CA2304":{"i":"CA2304","entryRequirements":"Applicants must have a relevant degree or professional qualification and provide a portfolio of professional work.  Special admission may apply.  They must also meet English language requirements and any programme specific criteria.  Contact Unitec for full details.","strategicPurposeStatement":"Graduates from this programme will possess advanced knowledge of theory and practice within their discipline, carry out professional research, use scholarly theory to appraise and contribute to the discipline, and be able to challenge existing thinking and contribute original ideas or inventions.","developedBy":"Manukau Institute of Technology and Unitec - Unitec","qualityAssuredBy":"Quality Assurance Division, NZQA","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CA2304"},"VI006K":{"i":"VI006K","entryRequirements":"1. (a) Before enrolment, a candidate for the MCBSc(Res) degree shall have:  (i) completed the PGDipCBSc or an equivalent qualification, with an average grade of at least B; and  (ii) been accepted by the Head of School as capable of proceeding with the proposed course of study.  (b) In exceptional circumstances, requirement (a)(i) may be waived by the Associate Dean (Postgraduate Research) for a candidate who has had extensive practical, professional, or scholarly experience that provides equivalent preparation.","strategicPurposeStatement":"Graduates will have an advanced-level understanding of construction, building science and technologies in a range of contexts and scales, with an emphasis on research into a selected aspect of the built environment. They will be able to access, interpret, critique and apply relevant research and disciplinary tools within an academic context. Graduates will use their advanced knowledge to undertake and communicate research on aspects of the built environment and the construction industry. Graduates will be well qualified to take on roles in academic units and research organisations related to the built environment and may be able to continue to doctoral study.","graduateProfile":"120-point thesis with regular academic supervision.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI006K"},"LI0198":{"i":"LI0198","entryRequirements":"A relevant bachelors degree.","strategicPurposeStatement":"Graduates of this programme will gain advanced skills and knowledge in an aspect of landscape design.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI0198"},"AU5718":{"i":"AU5718","entryRequirements":"Completed the requirements for a relevant Bachelors degree (excluding the Bachelor of Property) with a minimum GPA or completed the requirements for a relevant bachelors degree and passed 60 points in the Postgraduate Certificate in Property Practice with a minimum GPA.","strategicPurposeStatement":"The PGDipPropPrac will equip graduates for entry into careers in property practice. They are expected to have the capabilities required to apply appropriate problem-solving and analytical methods and techniques to solve property problems. They will demonstrate a specialist understanding of theory and practice in property and property-related fields and be able to apply this in current property management, valuation and investment contexts.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5718"},"VI00W6":{"i":"VI00W6","entryRequirements":"Bachelor's degree or equivalent qualification in a relevant subject","strategicPurposeStatement":"Graduates from the Postgraduate Diploma in Architecture programme will have demonstrated the ability to implement a chosen design strategy consistently through all stages of the design process and understand the role of the professional architect in contemporary society","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00W6"},"LI0598":{"i":"LI0598","entryRequirements":"A relevant bachelors degree.","strategicPurposeStatement":"Graduates of this programme will gain advanced skills and knowledge in an aspect of landscape design.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI0598"},"AU5719":{"i":"AU5719","entryRequirements":"Completed the requirements for a relevant Bachelor degree (excepting the Bachelor of Property) or has equivalent professional experience.","strategicPurposeStatement":"Graduates with a PGCertPropPrac will have attained a set of capabilities in either a generalist or specialist area of study related to property and be equipped to enter career pathways in property and related industries.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5719"},"VI003K":{"i":"VI003K","entryRequirements":"A bachelor's degree in architectural studies or building science, or equivalent, with an average grade of at least B.","strategicPurposeStatement":"Graduates will have a good level of understanding of architectural science, with an emphasis on managing the development or ongoing performance of the built environment. They will be able to access, interpret and apply relevant research and disciplinary tools within the professional context. Graduates will also be able to write and present their ideas in a professional manner and be able to use their advanced knowledge to improve the quality of the built environment. They will have the skills for management roles in the construction and building performance sectors.  Some graduates may choose to continue to a research-based master's degree such as the Master of Architectural Science (Research).","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI003K"},"LI0426":{"i":"LI0426","entryRequirements":"A relevant bachelors degree with appropriate grades.","strategicPurposeStatement":"Graduates will have advanced skills and knowledge in design and planning in landscape architecture through coursework and research.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI0426"},"AU5595":{"i":"AU5595","entryRequirements":"This is an exit qualification. Students need to have been enrolled in the MEnergy and passed at least 30 points for that degree, and been recommended for admission by the Dean or nominee","strategicPurposeStatement":"PGCertHerCons graduates will have explored the theory and documents that can inform heritage conservation practice internationally and in New Zealand.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5595"},"AK1338":{"i":"AK1338","entryRequirements":"Completion of Bachelor of Architecture and Future Environments or equivalent, with a B grade average or higher in papers at level 7. May be required to submit a portfolio or work and/or attend a selection interview.","strategicPurposeStatement":"Graduates will be well-rounded, reflective practitioners equipped not only to engage in research and professional practice but equally to strategically lead, innovate, manage and advocate for the future of the discipline. They will be able to integrate different strands of social and technical knowledge into core design processes and to design a range of buildings at different scales and levels of complexity. They will have acquired the applied research capability to contribute to the social and technical skills-base of the profession, and be at ease working collaboratively, in multi-disciplinary teams or in diverse cultural settings.  Students who complete the accredited MArch(Prof) and subsequent approved period of practical experience will be eligible to take the professional practice interview to become registered architects.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1338"},"AU5794":{"i":"AU5794","entryRequirements":"A relevant Bachelors degree with a minimum Grade Point Average (GPA).","strategicPurposeStatement":"The programme equips graduates with advanced analytical, critical, and creative capabilities, preparing them for leadership roles as designers, consultants, or client liaisons within architecture and related creative industries, such as media and web design.?","graduateProfile":"A number of different assessments modes are included, depending on the nature and specialisation of the original programme.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5794"},"MY0057":{"i":"MY0057","entryRequirements":"Admission to the Bachelor of Construction (Honours) requires that the candidate meet the University admission requirements as specified; and have been awarded or qualified for a construction-related Bachelors Degree, having achieved a B+ grade average from the majoring courses of the intended subject, or equivalent.","strategicPurposeStatement":"Bachelor of Construction (Honours) graduates will have research knowledge, specifically the ability to design and undertake a project under supervision, and to report this in an appropriate way, with discipline specific competencies in their discipline area of Construction Management or Quantity Surveying gained from their Bachelor of Construction programme.    Graduates are able to apply the importance of Te Tiriti o Waitangi, and Maori as tangata whenua, to the New Zealand construction industry. They also recognise that New Zealand is a Pacific nation, and have the knowledge and skills to operate locally, in the Pacific region, and internationally.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0057"},"MY0258":{"i":"MY0258","entryRequirements":"Three year Bachelor degree or Graduate Diploma in Construction or equivalent.","strategicPurposeStatement":"A graduate of the Postgraduate Diploma in Construction will be able to apply knowledge of construction technology or infrastructure management in the broadest perspective and in ways that accord with international best practice.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0258"},"AU5668":{"i":"AU5668","entryRequirements":"Completed the Degree of Bachelor of Architectural Studies  with a minimum Grade Point Average (GPA)","strategicPurposeStatement":"PGCertAPM graduates will be critically reflective practitioners who have advanced knowledge and understanding of architectural project management. Graduates will be prepared for careers in architectural project management and for taking leadership in architectural projects. They will also be prepared for further postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5668"},"VI005Z":{"i":"VI005Z","entryRequirements":"An approved Bachelors degree in a relevant discipline with an average grade of at least B.","strategicPurposeStatement":"Graduates from the MConsLaw programme will be able to demonstrate the critical and effective use of construction law and dispute resolution mechanisms to address construction-related projects issues in Aotearoa New Zealand, Australasia and globally. Graduates will be able to recognise the impact and importance of tikanga and Te Tiriti o Waitangi for construction projects. Graduates will be capable of integrating the necessary knowledge and investigating best practices and trends in construction management and law to identify appropriate solutions and decision-making strategies arising from contractual relationships while developing sophisticated and culturally-appropriate communication, interpersonal and transferable skills relevant to a diverse range of employment scenarios. Graduates will be able to demonstrate autonomy, expert judgement, adaptability and professional integrity as a practitioner in construction law.","graduateProfile":"The assessments for the courses will include individual and group assignments, tutorials, written reports, verbal presentations, reflective summaries, blogs and quizzes where appropriate.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005Z"},"VI003I":{"i":"VI003I","entryRequirements":"A bachelor's degree in architectural studies or building science, or equivalent, with an average grade of at least B.","strategicPurposeStatement":"Graduates will have advanced knowledge of architectural science, with an emphasis on managing the development and ongoing performance of the built environment at different scales and in different contexts.  They will be able to access, interpret, critique and apply relevant research and disciplinary tools within a professional context. Graduates will be able to write and present their ideas in a professional manner and will be able to use their advanced knowledge to improve the quality of the built environment. Graduates will be well qualified to take on leadership roles in the construction and building performance and management sectors.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI003I"},"LI1007":{"i":"LI1007","entryRequirements":"A New Zealand University entrance qualification or equivalent.  Candidates who hold a bachelor's degree can complete a modified course of study over four semesters.","strategicPurposeStatement":"Graduates of the BLA(Hons) will have professional skills in design practice and implementation.  Graduates will be able to create sustainable, high-quality environments with the most effective use of resources to create places and landscapes that enrich our identity, provide stimulating and uplifting experiences, meet socio-economic and functional needs, and sustain and enhance ecological and cultural values.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI1007"},"LI7580":{"i":"LI7580","entryRequirements":"Entry is by completion of an undergraduate degree relevant to planning with a B average at 300 level.","strategicPurposeStatement":"MPlan graduates will demonstrate an advanced level of understanding of the practical and theoretical underpinnings of this discipline and will be able to engage in research and debate on current issues in planning.  Graduates with upper level honours degrees would meet the requirements for advancing to a doctoral programme.  The Master of Planning Degree will meet the New Zealand Planning Institute's accreditation requirements and its graduates will be eligible for graduate membership of the New Zealand Planning Institute. The two year masters is consistent with similar offerings at Otago, Massey and Auckland Universities and it reflects this industry's needs for a coherency in advanced level professional skills and knowledge in planning practice, methods and theories, able to be applied in a wide variety of situations and different levels of governance. This supports an employment pathway into the field of urban, regional and environmental planning. Evaluation and application of policy and planning theory are, to some extent, generic skills that are required in most management positions and the degree provides the ability to move beyond the specifically planning field.  Contribution to community: It is worth noting that New Zealand's policy and planning framework has changed as a result of the Canterbury earthquakes and that Lincoln University is uniquely suited to make meaningful contributions to the wider community's on-going recovery effort and scholarship around that.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI7580"},"VI006L":{"i":"VI006L","entryRequirements":"1. (a) Before enrolment, a candidate for the PGCertCBSc shall have:  (i) completed a BBSc, BConst or BAS degree or an equivalent qualification, with an average grade of at least B; and  (ii) been accepted by the Head of School as capable of proceeding with the proposed course of study.  (b) Requirement (a)(i) may be waived by the Programme Director for a candidate who has had extensive practical, professional, or scholarly experience that provides equivalent preparation.","strategicPurposeStatement":"Graduates will possess a foundation in construction and building science, emphasising sustainable design, building performance, construction techniques and technology integration in the built environment.","graduateProfile":"Up to four taught courses in one trimester; at least 30 points drawn from the specified subject area.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI006L"},"VI006M":{"i":"VI006M","entryRequirements":"1. (a) Before enrolment, a candidate for the PGDipCBSc shall have:  (i) completed a BBSc, BConst or BAS degree or an equivalent qualification, with an average grade of at least B; and  (ii) been accepted by the Head of School as capable of proceeding with the proposed course of study.  (b) Requirement (a)(i) may be waived by the Programme Director for a candidate who has had extensive practical, professional, or scholarly experience that provides equivalent preparation.","strategicPurposeStatement":"Graduates will possess knowledge and skills in construction and building science, specialising in a chosen area. They will be able to analyse building performance issues, develop and evaluate innovative construction solutions for sustainable and high-performance buildings, and apply simulation and analysis tools to optimise building design, construction and operation.","graduateProfile":"Eight taught courses; four satisfy the subject requirement.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI006M"},"AU5177":{"i":"AU5177","entryRequirements":"A Bachelor of Architectural Studies degree or approved equivalent (normally with a B- grade average or better over 90 points at Year 3 of the BAS).","strategicPurposeStatement":"MArch(Prof) graduates will know and understand the process for the design and procurement of buildings of all types, and subject to mandatory experience, be prepared for statutory registration as an architect in New Zealand. They will also be prepared for further study at doctoral level.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5177"},"VI00U6":{"i":"VI00U6","entryRequirements":"A Victoria University Bachelor of Architectural Studies degree in Interior Architecture or a Graduate Diploma in Designed Environments in Interior Architecture or equivalent qualification.","strategicPurposeStatement":"Graduates from the Master of Interior Architecture programme will have demonstrated the ability to: independently research interior architecture specific issues and questions through advanced modes of design inquiry; implement a chosen design strategy consistently through all stages of the design process; effectively document, represent and express research findings, questions and processes through advanced means of communication; and understand the role of the professional interior architect in the context of the legal and institutional frameworks of contemporary multi-disciplinary built environment industries.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00U6"},"VI0038":{"i":"VI0038","entryRequirements":"Bachelor of Architecture or a Postgraduate Diploma in Architecture History and Theory or extensive practical and professional experience.","strategicPurposeStatement":"A Master of Architecture graduate will have obtained advanced understanding of architecture through research-based study, and developed skills in intellectual analysis, criticism and problem-solving.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0038"},"VI006J":{"i":"VI006J","entryRequirements":"1. (a) Before enrolment, a candidate for the MBSc degree shall have:  (i) completed a BBSc degree of this University, or, at the discretion of the Associate Dean (Students) of the Faculty of Architecture and Design, another degree; and  (ii) been accepted by the Head of the School of Architecture as capable of proceeding with the proposed course of study.  (b) Requirement (a)(i) may be waived by the Associate Dean for a candidate who has extensive professional or scholarly experience of an appropriate kind.","strategicPurposeStatement":"Graduates will have advanced knowledge of building science and technologies, with an emphasis on managing the development and ongoing performance of the built environment at different scales and in different contexts. They will be able to access, interpret, critique and apply relevant research and disciplinary tools within a professional context. Graduates will be able to write and present their ideas in a professional manner and will be able to use their advanced knowledge to improve the quality of the built environment. Graduates will be well qualified to take on leadership roles in building performance and management sectors.","graduateProfile":"60 points coursework in Trimesters 1-2, then a 60-point industry-based practicum/project in Trimester 3.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI006J"},"CA2302":{"i":"CA2302","entryRequirements":"Applicants must have a relevant degree or professional qualification and provide a portfolio of professional work. Special admission may apply. They must also meet English language requirements.","strategicPurposeStatement":"Graduates from this programme will have advanced knowledge of relevant theory and practice, challenge existing thinking and contribute original ideas; access, analyse and interpret data; carry out rigorous, sensitive and ethical research and use media to present outcomes.","developedBy":"Manukau Institute of Technology and Unitec - Unitec","qualityAssuredBy":"Quality Assurance Division, NZQA","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CA2302"},"AU5634":{"i":"AU5634","entryRequirements":"A student must have been enrolled in the Degree MArch(Prof) or MArch(Prof)HerCons, or MArch(Prof)UrbDes, or MArch(Prof)UrbPlan(Prof) and passed 30 points for that degree","strategicPurposeStatement":"Graduates will have the knowledge and skill to undertake advanced design work in the field of Architecture.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5634"},"AU5548":{"i":"AU5548","entryRequirements":"Bachelor of Architectural Studies or an equivalent qualification.","strategicPurposeStatement":"Graduates will have developed high level skills, knowledge and understanding in a critical mix of practical and theoretical areas in more than one discipline within the built environment. They will understand the practical application of the theory to practice.","graduateProfile":"Not applicable","educationPathway":"Not applicable","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5548"},"VI005X":{"i":"VI005X","entryRequirements":"An approved Bachelors degree in a relevant discipline with an average grade of at least B.","strategicPurposeStatement":"Graduates from the PGCertConsLaw will use their knowledge to improve the quality of their legal advice.","graduateProfile":"The assessments for the courses will include individual and group assignments, tutorials, written reports, verbal presentations, reflective summaries, blogs and quizzes where appropriate.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005X"},"AU5154":{"i":"AU5154","entryRequirements":"A Bachelor of Architectural Studies or equivalent degree and high average grades as determined by the Head of School of Architecture.","strategicPurposeStatement":"Postgraduate Diploma in Architecture graduates will have advanced knowledge and skills in their chosen field of Architecture. They will be able to critically evaluate and reflect upon their professional role and practice and engage in academically rigorous research projects.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5154"},"AU5545":{"i":"AU5545","entryRequirements":"A relevant degree such as Architecture, Arts, Engineering, Planning or Urban Planning with a minimum Grade Point Average (GPA), or its equivalent.  Previous study must be in a field relevant to the chosen specialisation.","strategicPurposeStatement":"Graduates will understand the theory and documents that inform heritage conservation practice internationally and in New Zealand. They will also understand the practical application of the theory to practice, industry and local case studies.","graduateProfile":"Not applicable","educationPathway":"Not applicable","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5545"},"AU5732":{"i":"AU5732","entryRequirements":"Must be admitted to and passed at least 30 points in the Master of Housing Studies, and been recommended for admission by the Dean or nominee.","strategicPurposeStatement":"PGCertHousSt graduates will have skills, knowledge and understanding of the theory and practice of housing design, sustainability, policy, affordability and regulation, with a focus on the New Zealand situation. They will be experienced in the application of the theory into practice, through analysis of the industry and local case studies. They will be reflective practitioners, able to pursue personal professional goals.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5732"}};
